// An explicit context budget, because "it fits" is not a design.
public class ContextBudget
{
    public int TotalWindow { get; init; } = 128_000;
    public int ReservedForResponse { get; init; } = 4_000;
    public int SystemPrompt { get; init; } = 800;
    public int MaxHistory { get; init; } = 8_000;

    public int AvailableForRetrieval =>
        TotalWindow - ReservedForResponse - SystemPrompt - MaxHistory;

    // Cost is asymmetric: output tokens usually cost several times input tokens.
    public decimal EstimateCost(int inputTokens, int outputTokens,
        decimal inputPerMillion, decimal outputPerMillion) =>
        inputTokens / 1_000_000m * inputPerMillion +
        outputTokens / 1_000_000m * outputPerMillion;
}

// Worked example — the arithmetic an architect is expected to do on a whiteboard.
//
//   50,000 requests/month
//   8,000 input tokens each (system + history + 20 retrieved chunks)
//   800 output tokens each
//
//   Input:  50,000 x 8,000   = 400,000,000 tokens
//   Output: 50,000 x   800   =  40,000,000 tokens
//
//   At $2.50 / 1M input and $10.00 / 1M output:
//     input  = 400 x $2.50 = $1,000
//     output =  40 x $10.00 =  $400
//     total  = $1,400 / month
//
//   Halving retrieved context to 10 chunks (4,000 input tokens) saves $500/month
//   AND typically improves answer quality by reducing mid-context loss.

// Cosine similarity, and the cases that expose its limits.
public static float CosineSimilarity(ReadOnlySpan<float> a, ReadOnlySpan<float> b)
{
    if (a.Length != b.Length)
        throw new ArgumentException("Vectors must share a model and therefore a length.");

    float dot = 0, magA = 0, magB = 0;
    for (var i = 0; i < a.Length; i++)
    {
        dot += a[i] * b[i];
        magA += a[i] * a[i];
        magB += b[i] * b[i];
    }
    return dot / (MathF.Sqrt(magA) * MathF.Sqrt(magB) + 1e-10f);
}

// Typical observed similarities — note the third line:
//
//   "cancel my subscription" vs "how do I end my membership"      ~0.87  useful
//   "cancel my subscription" vs "what is the weather today"       ~0.31  useful
//   "policy covers flood damage" vs
//   "policy does NOT cover flood damage"                          ~0.94  DANGEROUS
//
// The third pair are opposites and the vector space says they are nearly
// identical. This is exactly why retrieval over contracts, policies or
// clinical text must combine keyword search with vector search, and why a
// reranker that actually reads the text earns its cost.

// Normalise once at write time; search then reduces to a dot product.
public static float[] Normalise(float[] vector)
{
    var magnitude = MathF.Sqrt(vector.Sum(v => v * v));
    return magnitude < 1e-10f ? vector : vector.Select(v => v / magnitude).ToArray();
}

// Routing policy as configuration, so changing it is a config change.
public class RoutingLlmProvider(
    IReadOnlyDictionary<string, ILlmProvider> providers,
    RoutingPolicy policy,
    ILogger<RoutingLlmProvider> logger) : ILlmProvider
{
    public async Task<LlmResponse> CompleteAsync(LlmRequest request, CancellationToken ct)
    {
        var modelKey = policy.Resolve(request.TaskType, request.EstimatedInputTokens);

        if (!providers.TryGetValue(modelKey, out var provider))
            throw new InvalidOperationException($"No provider registered for '{modelKey}'.");

        logger.LogInformation("Routing {TaskType} to {Model}", request.TaskType, modelKey);

        try
        {
            return await provider.CompleteAsync(request, ct);
        }
        catch (Exception ex) when (IsTransient(ex) && policy.Fallback is { } fallbackKey)
        {
            // Failover must be a deliberate, logged decision: the fallback model
            // may behave differently and that shows up in evaluation data.
            logger.LogWarning(ex, "{Model} failed; falling back to {Fallback}", modelKey, fallbackKey);
            return await providers[fallbackKey].CompleteAsync(request, ct);
        }
    }
}

