// An evaluation harness small enough to actually maintain.
public record EvalCase(
    string Question,
    string[] ExpectedDocumentIds,   // retrieval ground truth
    string[] MustMention,           // facts a correct answer contains
    bool ShouldRefuse);             // true when the corpus cannot answer it

public class RagEvaluator(IRagPipeline pipeline, IJudge judge)
{
    public async Task<EvalReport> RunAsync(IReadOnlyList<EvalCase> cases, CancellationToken ct)
    {
        var results = new List<CaseResult>();

        foreach (var c in cases)
        {
            var response = await pipeline.AskAsync(c.Question, ct);

            // Retrieval recall@k: did we even fetch the right source?
            var retrieved = response.Citations.Select(x => x.DocumentId).ToHashSet();
            var recall = c.ExpectedDocumentIds.Length == 0
                ? 1.0
                : (double)c.ExpectedDocumentIds.Count(retrieved.Contains) / c.ExpectedDocumentIds.Length;

            // Deterministic checks — cheap, and they catch the worst failures.
            var refusedCorrectly = c.ShouldRefuse == response.IsRefusal;
            var mentioned = c.MustMention.Count(m =>
                response.Answer.Contains(m, StringComparison.OrdinalIgnoreCase));
            var coverage = c.MustMention.Length == 0
                ? 1.0 : (double)mentioned / c.MustMention.Length;

            // Model-as-judge: is every claim supported by the retrieved context?
            var groundedness = c.ShouldRefuse
                ? 1.0
                : await judge.ScoreGroundednessAsync(c.Question, response.Answer, response.Context, ct);

            results.Add(new CaseResult(c.Question, recall, coverage, groundedness,
                refusedCorrectly, response.LatencyMs, response.CostUsd));
        }

        return new EvalReport(
            RetrievalRecall: results.Average(r => r.Recall),
            FactCoverage: results.Average(r => r.Coverage),
            Groundedness: results.Average(r => r.Groundedness),
            RefusalAccuracy: results.Count(r => r.RefusedCorrectly) / (double)results.Count,
            P95LatencyMs: results.Select(r => r.LatencyMs).OrderBy(x => x).ElementAt((int)(results.Count * 0.95)),
            AverageCostUsd: results.Average(r => r.CostUsd),
            Cases: results);
    }
}

// The narrow interface the rest of the application sees.
public interface ILlmProvider
{
    string Name { get; }
    Task<LlmResponse> CompleteAsync(LlmRequest request, CancellationToken ct = default);
    IAsyncEnumerable<LlmChunk> StreamAsync(LlmRequest request, CancellationToken ct = default);
}

public record LlmRequest
{
    public required IReadOnlyList<LlmMessage> Messages { get; init; }
    public string? SystemPrompt { get; init; }
    public string? Model { get; init; }
    public float Temperature { get; init; } = 0.2f;
    public int MaxTokens { get; init; } = 2048;
    public IReadOnlyList<ToolDefinition>? Tools { get; init; }
    public JsonSchema? ResponseSchema { get; init; }
}

public record LlmResponse(
    string Content,
    IReadOnlyList<ToolCall> ToolCalls,
    TokenUsage Usage,          // never optional: cost tracking depends on it
    string FinishReason,
    string Model);

// Azure OpenAI adapter — the SDK appears only here.
public class AzureOpenAiProvider(AzureOpenAIClient client, IOptions<AzureOpenAiOptions> options)
    : ILlmProvider
{
    public string Name => "azure-openai";

    public async Task<LlmResponse> CompleteAsync(LlmRequest request, CancellationToken ct = default)
    {
        var chat = client.GetChatClient(request.Model ?? options.Value.DefaultDeployment);

        var messages = new List<ChatMessage>();
        // OpenAI models take the system prompt as the first message;
        // the Anthropic adapter passes it as a top-level parameter instead.
        if (request.SystemPrompt is { Length: > 0 } system)
            messages.Add(new SystemChatMessage(system));

        messages.AddRange(request.Messages.Select(m => m.Role switch
        {
            MessageRole.User => (ChatMessage)new UserChatMessage(m.Content),
            MessageRole.Assistant => new AssistantChatMessage(m.Content),
            _ => new UserChatMessage(m.Content)
        }));

        var completion = await chat.CompleteChatAsync(messages, new ChatCompletionOptions
        {
            Temperature = request.Temperature,
            MaxOutputTokenCount = request.MaxTokens
        }, ct);

        var usage = completion.Value.Usage;
        return new LlmResponse(
            completion.Value.Content[0].Text,
            ToolCalls: [],
            new TokenUsage(usage.InputTokenCount, usage.OutputTokenCount,
                options.Value.CostFor(usage.InputTokenCount, usage.OutputTokenCount)),
            completion.Value.FinishReason.ToString(),
            request.Model ?? options.Value.DefaultDeployment);
    }

    public IAsyncEnumerable<LlmChunk> StreamAsync(LlmRequest request, CancellationToken ct = default) =>
        StreamCoreAsync(request, ct);
}

