// Server: SSE endpoint with cancellation, heartbeats and mid-stream errors.
[HttpPost("stream")]
public async Task StreamAsync([FromBody] ChatRequest request, CancellationToken ct)
{
    Response.Headers.ContentType = "text/event-stream";
    Response.Headers.CacheControl = "no-cache";
    Response.Headers.Connection = "keep-alive";
    // Without this, a proxy may buffer the whole response and defeat streaming.
    Response.Headers["X-Accel-Buffering"] = "no";

    var accumulated = new StringBuilder();
    var usage = TokenUsage.Empty;

    try
    {
        // ct is RequestAborted: closing the tab stops generation and stops the cost.
        await foreach (var chunk in chatService.StreamAsync(request, ct))
        {
            if (chunk.Kind == ChunkKind.Content)
            {
                accumulated.Append(chunk.Text);
                await WriteEventAsync("token", new { text = chunk.Text }, ct);
            }
            else if (chunk.Kind == ChunkKind.Usage)
            {
                usage = chunk.Usage!;
            }
        }

        await WriteEventAsync("done", new
        {
            promptTokens = usage.PromptTokens,
            completionTokens = usage.CompletionTokens,
            costUsd = usage.EstimatedCostUsd
        }, ct);
    }
    catch (OperationCanceledException)
    {
        // Expected when the user navigates away. Keep the partial answer.
        logger.LogInformation("Stream cancelled by client after {Chars} characters", accumulated.Length);
    }
    catch (Exception ex)
    {
        // A 200 is already on the wire — the error has to travel as an event.
        logger.LogError(ex, "Stream failed mid-generation");
        await WriteEventAsync("error", new { message = "Generation failed. Partial response shown." }, CancellationToken.None);
    }
    finally
    {
        // Persist server-side; never trust the client to send the answer back.
        if (accumulated.Length > 0)
            await conversations.AppendAssistantMessageAsync(
                request.ConversationId, accumulated.ToString(), usage, CancellationToken.None);
    }
}

private async Task WriteEventAsync(string name, object payload, CancellationToken ct)
{
    await Response.WriteAsync($"event: {name}\n", ct);
    await Response.WriteAsync($"data: {JsonSerializer.Serialize(payload)}\n\n", ct);
    await Response.Body.FlushAsync(ct);   // flush every chunk, or nothing streams
}

// Schema designed for reliable extraction — flat, enumerated, and with an
// explicit way to say "I do not know".
public record InvoiceExtraction
{
    public required string VendorName { get; init; }
    public required string InvoiceNumber { get; init; }
    public required string InvoiceDate { get; init; }        // ISO 8601
    public required decimal TotalAmount { get; init; }
    public required string Currency { get; init; }           // ISO 4217
    public required ExtractionConfidence Confidence { get; init; }
    // Without this the model has no way to flag a problem except by inventing values.
    public required string[] FieldsNotFound { get; init; }
}

public enum ExtractionConfidence { High, Medium, Low, Unreadable }

public class InvoiceExtractor(ILlmProvider llm, ILogger<InvoiceExtractor> logger)
{
    public async Task<InvoiceExtraction?> ExtractAsync(string documentText, CancellationToken ct)
    {
        var request = new LlmRequest
        {
            SystemPrompt = """
                Extract invoice fields from the supplied document text.
                Use ISO 8601 for dates and ISO 4217 for currency.
                If a field is absent or unreadable, list its name in fieldsNotFound
                and set confidence accordingly. Never guess a value.
                """,
            Messages = [new LlmMessage(MessageRole.User, documentText)],
            ResponseSchema = JsonSchema.FromType<InvoiceExtraction>(),
            Temperature = 0f   // extraction is not a creative task
        };

        for (var attempt = 1; attempt <= 2; attempt++)
        {
            var response = await llm.CompleteAsync(request, ct);
            try
            {
                var extracted = JsonSerializer.Deserialize<InvoiceExtraction>(response.Content, Json)
                                ?? throw new JsonException("Null result");

                // Schema compliance is not correctness. Business rules run here.
                if (!DateOnly.TryParse(extracted.InvoiceDate, out var date))
                    throw new ValidationException($"Unparseable date '{extracted.InvoiceDate}'");
                if (date > DateOnly.FromDateTime(DateTime.UtcNow.AddDays(1)))
                    throw new ValidationException("Invoice date is in the future");
                if (extracted.TotalAmount <= 0)
                    throw new ValidationException("Total must be positive");

                return extracted;
            }
            catch (Exception ex) when (ex is JsonException or ValidationException && attempt == 1)
            {
                // One corrective retry with the specific failure fed back.
                logger.LogWarning("Extraction attempt 1 failed: {Error}", ex.Message);
                request = request with
                {
                    Messages = [.. request.Messages,
                        new LlmMessage(MessageRole.Assistant, response.Content),
                        new LlmMessage(MessageRole.User, $"That failed validation: {ex.Message}. Correct it.")]
                };
            }
        }

        return null;   // route to human review rather than guessing
    }
}

// Every tool execution goes through authorisation. No exceptions.
public class AuthorisedToolExecutor(
    IReadOnlyDictionary<string, ITool> tools,
    ICurrentUser currentUser,
    IAuditLog audit,
    ILogger<AuthorisedToolExecutor> logger)
{
    public async Task<ToolResult> ExecuteAsync(ToolCall call, CancellationToken ct)
    {
        if (!tools.TryGetValue(call.Name, out var tool))
            return ToolResult.Error($"Unknown tool '{call.Name}'.");

        var userId = currentUser.RequireUserId();

        // 1. Is this user allowed to use this tool at all?
        if (!await tool.IsAuthorisedAsync(userId, ct))
        {
            await audit.RecordDeniedAsync(userId, call.Name, call.Arguments, ct);
            // Deliberately unhelpful to the caller, fully detailed in the audit log.
            return ToolResult.Error("You do not have access to this capability.");
        }

        // 2. Are the ARGUMENTS within this user's entitlements?
        //    This is the check that stops "show me orders for customer 4471".
        var argumentCheck = await tool.ValidateArgumentsAsync(userId, call.Arguments, ct);
        if (!argumentCheck.IsAllowed)
        {
            await audit.RecordDeniedAsync(userId, call.Name, call.Arguments, ct);
            return ToolResult.Error(argumentCheck.Reason);
        }

        try
        {
            var result = await tool.ExecuteAsync(userId, call.Arguments, ct);
            await audit.RecordExecutedAsync(userId, call.Name, call.Arguments, result.IsSuccess, ct);
            return result;
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Tool {Tool} failed for {User}", call.Name, userId);
            // Structured error the model can reason about — never a raw exception.
            return ToolResult.Error("The tool failed. Do not retry; tell the user you could not complete this.");
        }
    }
}

public class GetCustomerOrdersTool(IOrderRepository orders, IEntitlements entitlements) : ITool
{
    public string Name => "get_customer_orders";

    public string Description =>
        """
        Retrieve orders for a customer the signed-in user is entitled to view.
        Use when the user asks about order status, history or delivery.
        Do not use for payment details or to modify an order.
        """;

    public Task<bool> IsAuthorisedAsync(Guid userId, CancellationToken ct) =>
        entitlements.HasPermissionAsync(userId, "orders.read", ct);

    public async Task<ArgumentCheck> ValidateArgumentsAsync(
        Guid userId, JsonElement args, CancellationToken ct)
    {
        if (!args.TryGetProperty("customerId", out var raw) || !Guid.TryParse(raw.GetString(), out var customerId))
            return ArgumentCheck.Deny("customerId is required and must be a GUID.");

        // The model proposed this ID. The database decides whether it is allowed.
        return await entitlements.CanAccessCustomerAsync(userId, customerId, ct)
            ? ArgumentCheck.Allow()
            : ArgumentCheck.Deny("That customer is not accessible to you.");
    }
}

