// Prompts live in the repository as versioned files, not in a database.
// /prompts/rag-assistant.v4.md

public class PromptCatalogue(IOptions<PromptOptions> options)
{
    private readonly ConcurrentDictionary<string, Prompt> _cache = new();

    public Prompt Get(string name) => _cache.GetOrAdd(name, key =>
    {
        var version = options.Value.ActiveVersions[key];
        var path = Path.Combine(options.Value.Directory, $"{key}.{version}.md");
        return new Prompt(key, version, File.ReadAllText(path));
    });
}

