// Hybrid memory: durable facts + rolling summary + recent turns verbatim.
public class ConversationMemory(
    ILlmProvider llm,
    ITokenCounter tokens,
    IConversationStore store)
{
    private const int HistoryBudget = 6_000;
    private const int RecentTurnsVerbatim = 6;

    public async Task<IReadOnlyList<LlmMessage>> BuildContextAsync(
        Guid conversationId, CancellationToken ct)
    {
        var conversation = await store.GetAsync(conversationId, ct);
        var messages = new List<LlmMessage>();

        // 1. Durable facts, extracted as they appear and carried separately from
        //    the transcript so they survive any amount of trimming.
        if (conversation.Facts.Count > 0)
            messages.Add(new LlmMessage(MessageRole.System,
                "Known facts about this conversation:\n" +
                string.Join('\n', conversation.Facts.Select(f => $"- {f.Key}: {f.Value}"))));

        var recent = conversation.Messages.TakeLast(RecentTurnsVerbatim).ToList();
        var older = conversation.Messages.SkipLast(RecentTurnsVerbatim).ToList();

        // 2. Summarise the middle once, then reuse it until it goes stale.
        if (older.Count > 0)
        {
            if (conversation.Summary is null ||
                conversation.SummarisedUpTo < older.Count - RecentTurnsVerbatim)
            {
                conversation.Summary = await SummariseAsync(older, ct);
                conversation.SummarisedUpTo = older.Count;
                await store.SaveAsync(conversation, ct);
            }

            messages.Add(new LlmMessage(MessageRole.System,
                $"Summary of earlier conversation:\n{conversation.Summary}"));
        }

        // 3. Recent turns verbatim, trimmed from the oldest if over budget.
        var used = messages.Sum(m => tokens.Count(m.Content));
        foreach (var message in recent)
        {
            var cost = tokens.Count(message.Content);
            if (used + cost > HistoryBudget) break;
            messages.Add(message);
            used += cost;
        }

        return messages;
    }

    private async Task<string> SummariseAsync(IReadOnlyList<LlmMessage> older, CancellationToken ct)
    {
        var response = await llm.CompleteAsync(new LlmRequest
        {
            SystemPrompt = """
                Summarise this conversation in under 200 words.
                Preserve: decisions made, constraints stated, identifiers mentioned,
                and open questions. Omit pleasantries.
                """,
            Messages = older,
            Temperature = 0f,
            MaxTokens = 400
        }, ct);

        return response.Content;
    }
}

// The query pipeline, with the decision points made explicit.
public class RagPipeline(
    IEmbeddingProvider embeddings,
    IHybridSearch search,
    IReranker reranker,
    ILlmProvider llm,
    PromptCatalogue prompts,
    RagOptions options)
{
    public async Task<RagAnswer> AskAsync(string question, ClaimsPrincipal user, CancellationToken ct)
    {
        // 1. Retrieve wide: hybrid search over a generous candidate set.
        var queryVector = await embeddings.EmbedAsync(question, ct);
        var candidates = await search.SearchAsync(new SearchQuery
        {
            Text = question,
            Vector = queryVector,
            TopK = options.CandidateCount,        // 50 — cast wide, rerank later
            Filter = PermissionFilter.For(user)   // enforced in the query, not the prompt
        }, ct);

        if (candidates.Count == 0)
            return RagAnswer.Refusal("I could not find anything relevant you have access to.");

        // 2. Rerank narrow: a cross-encoder reads the text properly.
        var ranked = await reranker.RerankAsync(question, candidates, options.ContextCount, ct);

        // 3. Refuse rather than answer from weak context.
        if (ranked[0].Score < options.MinimumRelevanceScore)
            return RagAnswer.Refusal("I could not find that in the available documents.");

        // 4. Build context with citation markers the model must reuse.
        var context = string.Join("\n\n", ranked.Select(r =>
            $"[{r.DocumentId}:{r.Page}]\n{r.Content}"));

        var prompt = prompts.Get("rag-assistant");
        var response = await llm.CompleteAsync(new LlmRequest
        {
            SystemPrompt = prompt.Text.Replace("{{CONTEXT}}", context),
            Messages = [new LlmMessage(MessageRole.User, question)],
            Temperature = 0.1f
        }, ct);

        // 5. A claim without a citation is not an answer.
        var citations = CitationParser.Extract(response.Content, ranked);
        if (citations.Count == 0 && !response.Content.Contains("could not find"))
            return RagAnswer.Refusal("I could not produce a properly sourced answer.");

        return new RagAnswer(response.Content, citations, ranked, response.Usage);
    }
}

// Structure-aware chunking with heading context and a size ceiling.
public class StructureAwareChunker(ITokenCounter tokens) : IChunker
{
    private const int TargetTokens = 300;
    private const int MaxTokens = 450;
    private const int OverlapTokens = 40;

    public IEnumerable<Chunk> Split(ParsedDocument document)
    {
        var index = 0;

        foreach (var section in document.Sections)
        {
            // The heading path is the single highest-value piece of context.
            // "Handbook > Leave > Parental Leave" massively improves retrieval.
            var headingPath = string.Join(" > ", section.HeadingPath);
            var prefix = $"{headingPath}\n\n";
            var prefixTokens = tokens.Count(prefix);

            // Tables never go through the text splitter: a table without its
            // headers retrieves confidently and answers wrongly.
            if (section.IsTable)
            {
                yield return new Chunk(index++, prefix + section.Text, headingPath,
                    section.Page, ChunkKind.Table);
                continue;
            }

            var buffer = new StringBuilder();
            var bufferTokens = 0;

            foreach (var paragraph in section.Paragraphs)
            {
                var paragraphTokens = tokens.Count(paragraph);

                // A single oversized paragraph is split on sentences instead.
                if (paragraphTokens > MaxTokens - prefixTokens)
                {
                    foreach (var piece in SplitOnSentences(paragraph, MaxTokens - prefixTokens))
                        yield return new Chunk(index++, prefix + piece, headingPath,
                            section.Page, ChunkKind.Text);
                    continue;
                }

                if (bufferTokens + paragraphTokens + prefixTokens > TargetTokens && bufferTokens > 0)
                {
                    var text = buffer.ToString();
                    yield return new Chunk(index++, prefix + text, headingPath,
                        section.Page, ChunkKind.Text);

                    // Overlap carries the tail forward so a boundary-spanning
                    // answer is still retrievable from the following chunk.
                    var tail = TakeLastTokens(text, OverlapTokens);
                    buffer.Clear().Append(tail).Append("\n\n");
                    bufferTokens = tokens.Count(tail);
                }

                buffer.Append(paragraph).Append("\n\n");
                bufferTokens += paragraphTokens;
            }

            if (bufferTokens > 0)
                yield return new Chunk(index++, prefix + buffer.ToString(), headingPath,
                    section.Page, ChunkKind.Text);
        }
    }
}

// Reciprocal rank fusion over two ranked lists.
public class HybridSearchService(
    IVectorStore vectors,
    IKeywordIndex keywords,
    HybridOptions options) : IHybridSearch
{
    private const int RrfK = 60;   // standard smoothing constant

    public async Task<IReadOnlyList<SearchHit>> SearchAsync(SearchQuery query, CancellationToken ct)
    {
        // Run both legs concurrently — they are independent.
        var vectorTask = vectors.SearchAsync(query.Vector, query.TopK, query.Filter, ct);
        var keywordTask = keywords.SearchAsync(query.Text, query.TopK, query.Filter, ct);
        await Task.WhenAll(vectorTask, keywordTask);

        var fused = new Dictionary<string, FusedHit>();

        // Rank, not score: BM25 and cosine are not on a comparable scale.
        for (var i = 0; i < vectorTask.Result.Count; i++)
        {
            var hit = vectorTask.Result[i];
            var contribution = options.VectorWeight / (RrfK + i + 1);
            fused[hit.Id] = new FusedHit(hit, contribution, vectorRank: i + 1, keywordRank: null);
        }

        for (var i = 0; i < keywordTask.Result.Count; i++)
        {
            var hit = keywordTask.Result[i];
            var contribution = options.KeywordWeight / (RrfK + i + 1);

            if (fused.TryGetValue(hit.Id, out var existing))
                fused[hit.Id] = existing with
                {
                    Score = existing.Score + contribution,
                    KeywordRank = i + 1
                };
            else
                fused[hit.Id] = new FusedHit(hit, contribution, vectorRank: null, keywordRank: i + 1);
        }

        return fused.Values
            .OrderByDescending(f => f.Score)
            .Take(query.TopK)
            // Ranks are carried through: invaluable when diagnosing why a
            // document was or was not retrieved.
            .Select(f => f.Hit with { Score = f.Score, VectorRank = f.VectorRank, KeywordRank = f.KeywordRank })
            .ToList();
    }
}

// Permission filtering, freshness, reranking and deduplication in order.
public class SecureRetriever(
    IHybridSearch search,
    IReranker reranker,
    RetrievalOptions options)
{
    public async Task<IReadOnlyList<SearchHit>> RetrieveAsync(
        string question, ReadOnlyMemory<float> vector, ClaimsPrincipal user, CancellationToken ct)
    {
        var groups = user.FindAll("groups").Select(c => c.Value).ToArray();
        if (groups.Length == 0) return [];   // no entitlements, no results

        // Applied IN the query. Post-filtering would mean the content was
        // already loaded, already logged, and one bug from the response.
        var filter = new FilterBuilder()
            .AnyOf("acl", groups)
            .Equals("isCurrentVersion", true)          // no superseded documents
            .GreaterThan("effectiveDate", options.IgnoreOlderThan)
            .Build();

        var candidates = await search.SearchAsync(new SearchQuery
        {
            Text = question,
            Vector = vector,
            TopK = options.CandidateCount,   // 50
            Filter = filter
        }, ct);

        if (candidates.Count == 0) return [];

        // Cross-encoder: reads query and passage together. Accurate, and far too
        // slow to run across the whole index — which is why it runs here.
        var reranked = await reranker.RerankAsync(question, candidates, options.ContextCount * 2, ct);

        // Near-duplicates waste the context budget saying the same thing.
        return Deduplicate(reranked, options.ContextCount, options.DuplicateThreshold);
    }

    private static List<SearchHit> Deduplicate(
        IReadOnlyList<SearchHit> hits, int take, double threshold)
    {
        var kept = new List<SearchHit>();

        foreach (var hit in hits)
        {
            if (kept.Count >= take) break;

            var isDuplicate = kept.Any(k =>
                TextSimilarity.Jaccard(k.Content, hit.Content) > threshold);

            if (!isDuplicate) kept.Add(hit);
        }

        return kept;
    }
}

// Citations are parsed, validated against the retrieved set, and required.
public class CitationValidator
{
    private static readonly Regex Pattern = new(@"\[([a-zA-Z0-9\-]+):(\d+)\]", RegexOptions.Compiled);

    public CitationResult Validate(string answer, IReadOnlyList<SearchHit> context)
    {
        var available = context
            .Select(c => (Doc: c.DocumentId, Page: c.Page))
            .ToHashSet();

        var valid = new List<Citation>();
        var fabricated = new List<string>();

        foreach (Match match in Pattern.Matches(answer))
        {
            var documentId = match.Groups[1].Value;
            var page = int.Parse(match.Groups[2].Value);

            if (available.Contains((documentId, page)))
            {
                var hit = context.First(c => c.DocumentId == documentId && c.Page == page);
                valid.Add(new Citation(documentId, page, hit.Title, hit.Content));
            }
            else
            {
                // The model cited something that was never in the context.
                // Rare, but it happens, and it is exactly what users trust most.
                fabricated.Add(match.Value);
            }
        }

        return new CitationResult(valid, fabricated);
    }
}

// Three-layer refusal.
public async Task<RagAnswer> AnswerAsync(string question, ClaimsPrincipal user, CancellationToken ct)
{
    var context = await retriever.RetrieveAsync(question, user, ct);

    // Layer 1: refuse before spending a model call.
    if (context.Count == 0 || context[0].Score < options.MinimumRelevanceScore)
        return RagAnswer.Refusal(RefusalMessage);

    // Layer 2: the prompt specifies the exact refusal wording, so it is testable.
    var response = await llm.CompleteAsync(BuildRequest(question, context), ct);

    var citations = validator.Validate(response.Content, context);

    if (citations.Fabricated.Count > 0)
        logger.LogWarning("Model produced {Count} unresolvable citations: {Citations}",
            citations.Fabricated.Count, string.Join(", ", citations.Fabricated));

    // Layer 3: an uncited, non-refusal answer is a failure, not a result.
    var isRefusal = response.Content.Contains(RefusalMessage, StringComparison.OrdinalIgnoreCase);
    if (citations.Valid.Count == 0 && !isRefusal)
    {
        logger.LogWarning("Ungrounded answer suppressed for question: {Question}", question);
        return RagAnswer.Refusal(RefusalMessage);
    }

    return new RagAnswer(response.Content, citations.Valid, context, response.Usage);
}

// Parameter sweep: change one dimension at a time and record everything.
public class RagTuner(IRagPipelineFactory factory, RagEvaluator evaluator)
{
    public async Task<IReadOnlyList<TuningRun>> SweepAsync(
        IReadOnlyList<EvalCase> cases,
        RagOptions baseline,
        CancellationToken ct)
    {
        var runs = new List<TuningRun>();

        // Baseline first — everything is measured relative to it.
        runs.Add(await RunAsync("baseline", baseline, cases, ct));

        // One dimension at a time. Changing two tells you nothing about either.
        foreach (var contextCount in new[] { 5, 10, 15, 20 })
            runs.Add(await RunAsync($"context-{contextCount}",
                baseline with { ContextCount = contextCount }, cases, ct));

        foreach (var threshold in new[] { 0.3, 0.4, 0.5, 0.6 })
            runs.Add(await RunAsync($"threshold-{threshold}",
                baseline with { MinimumRelevanceScore = threshold }, cases, ct));

        runs.Add(await RunAsync("no-rerank", baseline with { UseReranker = false }, cases, ct));
        runs.Add(await RunAsync("vector-only", baseline with { KeywordWeight = 0 }, cases, ct));

        return runs;
    }

    private async Task<TuningRun> RunAsync(
        string label, RagOptions options, IReadOnlyList<EvalCase> cases, CancellationToken ct)
    {
        var report = await evaluator.RunAsync(factory.Create(options), cases, ct);
        return new TuningRun(label, options, report, DateTimeOffset.UtcNow);
    }
}

